$nodeScript = @'
const fs=require('fs'),{PNG}=require('pngjs'),pixelmatch=require('pixelmatch')
const ref=PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'))
const base=PNG.sync.read(fs.readFileSync('C:/Users/Administrator/.dsh/attachments/v1/objects/3a/3a11aed43af6bbd863f34916990b7d839fbf3570f4af9c5015071b7346142dde'))
const alt=PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'))
const items=[['工作中心',514],['数据大屏',653],['行业管理',779],['项目管理',905],['业主自治',1031],['共有资金',1157],['阳光物业',1283],['公共查询',1409],['设施设备',1535],['公共信息',1661]]
function crop(im,x,y,w,h){let out=Buffer.alloc(w*h*4);for(let r=0;r<h;r++)im.data.copy(out,r*w*4,((y+r)*im.width+x)*4,((y+r)*im.width+x+w)*4);return out}
for(const [name,c] of items){let x=c-18,y=18,w=36,h=42,t=crop(ref,x,y,w,h),b=1-pixelmatch(crop(base,x,y,w,h),t,null,w,h,{threshold:.1,includeAA:false})/(w*h),a=1-pixelmatch(crop(alt,x,y,w,h),t,null,w,h,{threshold:.1,includeAA:false})/(w*h);console.log(`${name}: base=${(b*100).toFixed(1)}%, alt=${(a*100).toFixed(1)}%, delta=${((a-b)*100).toFixed(1)}pp`)}
'@
